        summary["effective_n"] = r2(sw * sw / sw2)
        summary["weight_min"] = r2(min(weights))
        summary["weight_max"] = r2(max(weights))

    # 6. tables
    columns = [("total", None, None)]
    for bq in plan.get("banner", []):
        q = qs[bq]
        opts = q["bands"] if q["type"] == "age" else [o for o in q["options"] if not o.get("missing")]
        for o in opts:
            columns.append((f"{bq}:{o['code']}", bq, o["code"]))

    tables = []
    for t in plan.get("tables", []):
        q = qs[t["question"]]
        if q["type"] == "age":
            rows_opts = list(q["bands"])
        else:
            rows_opts = [o for o in q["options"] if not o.get("missing")]
        scores = {o["code"]: o.get("score") for o in q.get("options", [])}
        cols_out = []
        for cid, bq, bcode in columns:
            idx = []
            for i, r in enumerate(final):
                a = r["ans"][q["id"]]
                if not (a[0] and a[1] is not None):
                    continue
                if bq is not None and r["ans"][bq][1] != bcode:
                    continue
                idx.append(i)
            wb = sum(weights[i] for i in idx)
            col = {"column": cid, "base": len(idx), "weighted_base": r2(wb)}
            values = {}

            def has(i, codes):
                a = final[i]["ans"][q["id"]][1]
                if isinstance(a, frozenset):
                    return bool(a & set(codes))
                return a in codes

            for o in rows_opts:
                key = str(o["code"])
                if not idx:
                    values[key] = None
                else:
                    values[key] = r2(100 * sum(weights[i] for i in idx if has(i, [o["code"]])) / wb)
            for net in t.get("nets", []):
                if not idx:
                    values[net["id"]] = None
                else:
                    values[net["id"]] = r2(100 * sum(weights[i] for i in idx if has(i, net["codes"])) / wb)
            if t.get("mean"):
                if not idx:
                    values["mean"] = None
                else:
                    values["mean"] = r2(sum(weights[i] * scores[final[i]["ans"][q["id"]][1]] for i in idx) / wb)
            col["values"] = values
            cols_out.append(col)
        tables.append({"table": t["id"], "columns": cols_out})

    out = {"survey": cb["survey"], "summary": summary, "tables": tables}
    with open(output_file, "w", encoding="utf-8") as f:
        json.dump(out, f, indent=1)
        f.write("\n")


